// ============================================================================
// 1 · NORMALIZE MESSAGE
// ----------------------------------------------------------------------------
// Turns ANY inbound payload into ONE canonical shape, so every node after this
// one is channel-agnostic. Accepted inputs:
//   • WhatsApp Trigger node output          (flattened Meta "value" object)
//   • Raw Meta webhook body                  (WhatsApp or Instagram "entry" array)
//   • Generic Webhook node output            ({ headers, query, body })
//   • ManyChat "External Request"            ({ channel, contact_id, text, ... })
//
// Output item (exactly one, or none):
//   channel       "whatsapp" | "instagram"
//   contact_id    phone number (WhatsApp) or Instagram-scoped user id (IGSID)
//   contact_key   "<channel>:<contact_id>"  → the key used in the Google Sheets
//   contact_name  profile name when the channel sends one, else ""
//   text          the customer's message (quick successive messages are joined)
//   message_id    platform message id (used to ignore duplicate deliveries)
//   message_type  "text" | "image" | "audio" | "video" | "document" | ...
//   received_at   ISO timestamp
//
// Delivery/read receipts, echoes of our own replies and empty payloads produce
// NO item, which simply ends the execution (nothing to answer).
// ============================================================================

const bySender = {};

function add(m) {
  if (!m.contact_id || !m.text) return;
  const key = `${m.channel}:${m.contact_id}`;
  if (!bySender[key]) {
    bySender[key] = {
      channel: m.channel,
      contact_id: String(m.contact_id),
      contact_key: key,
      contact_name: m.contact_name || '',
      text: m.text,
      message_id: String(m.message_id || `${key}:${m.ts}`),
      message_type: m.message_type || 'text',
      received_at: new Date(m.ts || Date.now()).toISOString(),
    };
  } else {
    // The customer sent several messages in one burst → treat as one turn.
    bySender[key].text += '\n' + m.text;
  }
}

function placeholder(type) {
  return `[The customer sent a ${type} message that the assistant cannot read]`;
}

// WhatsApp Cloud API: one "value" object = { metadata, contacts[], messages[] | statuses[] }
function handleWhatsAppValue(v) {
  const names = {};
  for (const c of v.contacts || []) names[c.wa_id] = (c.profile && c.profile.name) || '';
  for (const m of v.messages || []) {          // "statuses" payloads have no messages → ignored
    let text = '';
    if (m.type === 'text') text = (m.text && m.text.body) || '';
    else if (m.type === 'button') text = (m.button && m.button.text) || '';
    else if (m.type === 'interactive') {
      const i = m.interactive || {};
      text = (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title) || '';
    } else text = placeholder(m.type || 'unsupported');
    add({
      channel: 'whatsapp',
      contact_id: m.from,
      contact_name: names[m.from] || '',
      text: String(text).trim(),
      message_id: m.id,
      message_type: m.type || 'text',
      ts: m.timestamp ? Number(m.timestamp) * 1000 : Date.now(),
    });
  }
}

// Instagram Messaging API: one "messaging" event = { sender, recipient, timestamp, message }
function handleInstagramEvent(ev) {
  const msg = ev.message;
  if (!msg || msg.is_echo || msg.is_deleted) return;   // is_echo = our own outgoing message → never answer it
  let text = msg.text || '';
  let type = 'text';
  if (!text && msg.quick_reply && msg.quick_reply.payload) text = String(msg.quick_reply.payload);
  if (!text && Array.isArray(msg.attachments) && msg.attachments.length) {
    type = msg.attachments[0].type || 'attachment';
    text = placeholder(type);
  }
  add({
    channel: 'instagram',
    contact_id: ev.sender && ev.sender.id,
    contact_name: '',
    text: String(text).trim(),
    message_id: msg.mid,
    message_type: type,
    ts: ev.timestamp || Date.now(),
  });
}

for (const item of $input.all()) {
  let p = item.json || {};
  if (p.body && typeof p.body === 'object' && !p.messages && !p.entry) p = p.body;   // generic Webhook node → unwrap

  if (Array.isArray(p.messages) || Array.isArray(p.statuses) || p.messaging_product === 'whatsapp') {
    handleWhatsAppValue(p);                                   // WhatsApp Trigger node output
  } else if (Array.isArray(p.entry)) {                        // raw Meta webhook body
    for (const entry of p.entry) {
      for (const change of entry.changes || []) if (change.value) handleWhatsAppValue(change.value);
      for (const ev of entry.messaging || []) handleInstagramEvent(ev);
    }
  } else if (p.contact_id && p.text) {                        // ManyChat External Request (simple JSON)
    add({
      channel: p.channel === 'whatsapp' ? 'whatsapp' : 'instagram',
      contact_id: p.contact_id,
      contact_name: p.contact_name || '',
      text: String(p.text).trim(),
      message_id: p.message_id,
      message_type: 'text',
      ts: Date.now(),
    });
  }
}

// Meta sends one notification per sender, so the workflow handles ONE
// conversation per execution. (In the rare case a batch contains several
// senders only the first is processed — see README → Known limits.)
return Object.values(bySender).slice(0, 1).map((json) => ({ json }));

// ============================================================================
// 2 · ASSEMBLE CONTEXT
// ----------------------------------------------------------------------------
// Gathers everything the AI step needs into ONE item:
//   message   → the normalized customer message
//   config    → the per-client settings from "Client Config"
//   kb_text   → the approved knowledge base, formatted for the prompt (rows carry ids)
//   kb_rows   → the same rows as objects { id, category, title, content }
//   history   → the last N turns of this conversation (Claude message format)
//   lead      → the customer's existing row in the Leads sheet (or null)
//   triage    → "bot" | "human" | "ignore"
//       bot    = the assistant answers
//       human  = a person took over this chat (status = human in Leads) → stay silent, alert owner
//       ignore = Meta re-delivered a message we already processed (same message_id)
// ============================================================================

const message = $('Normalize Message').first().json;
const config = $('Client Config').first().json;
const zone = config.timezone || 'UTC';

// Google Sheets nodes return one empty item when nothing matches → drop those.
const rows = (items) => items.map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);

const kbRows = rows($('Load Knowledge Base').all());
const leadRows = rows($('Lookup Lead').all()).filter((r) => String(r.contact_key) === message.contact_key);
const logRows = rows($('Load Conversation History').all()).filter((r) => String(r.contact_key) === message.contact_key);

// --- Knowledge base → readable text, grouped by category ---------------------
// Every row gets a short id such as [S1] (services), [H2] (hours), [F3] (faq).
// The model must cite the ids it used (kb_refs); in strict mode the workflow
// sends those rows verbatim instead of the model's wording.
const ORDER = ['services', 'hours', 'location', 'booking', 'policies', 'faq'];
const groups = {};
const kb_rows = [];
const counters = {};
for (const r of kbRows) {
  const cat = String(r.category || 'faq').trim().toLowerCase();
  if (!r.title && !r.content) continue;
  counters[cat] = (counters[cat] || 0) + 1;
  const row = { id: `${cat.charAt(0).toUpperCase()}${counters[cat]}`, category: cat, title: String(r.title || '').trim(), content: String(r.content || '').trim() };
  kb_rows.push(row);
  (groups[cat] = groups[cat] || []).push(`- [${row.id}] ${row.title}: ${row.content}`);
}
const cats = [...ORDER.filter((c) => groups[c]), ...Object.keys(groups).filter((c) => !ORDER.includes(c))];
const kb_text = cats.map((c) => `## ${c.toUpperCase()}\n${groups[c].join('\n')}`).join('\n\n') || '(The knowledge base is empty.)';

// --- Timestamps: accept ISO strings, "yyyy-LL-dd HH:mm" or Sheets date serials
function parseWhen(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') return DateTime.fromMillis(Math.round((value - 25569) * 86400000), { zone });
  const s = String(value);
  let dt = DateTime.fromISO(s, { zone });
  if (!dt.isValid) dt = DateTime.fromFormat(s, 'yyyy-LL-dd HH:mm:ss', { zone });
  if (!dt.isValid) dt = DateTime.fromFormat(s, 'yyyy-LL-dd HH:mm', { zone });
  return dt.isValid ? dt : null;
}

// --- Conversation history → Claude messages (oldest first, last N turns) -----
logRows.sort((a, b) => {
  const ta = parseWhen(a.timestamp), tb = parseWhen(b.timestamp);
  return (ta ? ta.toMillis() : 0) - (tb ? tb.toMillis() : 0);
});
const maxTurns = Number(config.max_history_turns) || 10;
const history = [];
for (const r of logRows.slice(-maxTurns)) {
  if (r.customer_message) history.push({ role: 'user', content: String(r.customer_message) });
  if (r.bot_reply) history.push({ role: 'assistant', content: String(r.bot_reply) });
}

// --- Triage -------------------------------------------------------------------
const lead = leadRows[0] || null;
const is_duplicate = logRows.some((r) => r.message_id && String(r.message_id) === message.message_id);

let human_mode = false;
if (lead && String(lead.status || '').trim().toLowerCase() === 'human') {
  const since = parseWhen(lead.handoff_at);
  const hours = since ? (Date.now() - since.toMillis()) / 3600000 : 0;
  human_mode = hours < (Number(config.human_mode_timeout_hours) || 12);   // auto-resume the bot after the timeout
}

const triage = is_duplicate ? 'ignore' : human_mode ? 'human' : 'bot';

return [{ json: { message, config, lead, kb_text, kb_rows, kb_row_count: kb_rows.length, history, triage, is_duplicate, human_mode } }];

// ============================================================================
// 3 · BUILD CLAUDE REQUEST
// ----------------------------------------------------------------------------
// Builds the body for the Anthropic Messages API call. The design choices that
// keep the bot "limited to approved information" live here:
//   • the knowledge base is injected into the system prompt and the rules say
//     "answer ONLY from it, otherwise hand off";
//   • the reply is returned as STRICT JSON (output_config.format) so the
//     workflow — not the model — decides what is sent, booked or escalated;
//   • the model never confirms bookings; it only collects details.
// ============================================================================

const ctx = $input.first().json;
const { message, config, kb_text, history, lead } = ctx;
const zone = config.timezone || 'UTC';
const now = DateTime.now().setZone(zone);
const requireConsent = String(config.require_consent) === 'true';
const strictMode = String(config.reply_mode || 'assistant').toLowerCase() === 'strict';

const stableRules = `You are the virtual assistant of ${config.client_name} (${config.business_type}). You chat with customers on WhatsApp and Instagram.

STRICT RULES
1. Answer ONLY from the APPROVED KNOWLEDGE BASE below. If the answer is not there, do NOT guess, estimate or invent anything. Say you will check with the team and set needs_human = true.
2. Quote prices, durations, hours, addresses and policies exactly as written. Never offer discounts, promises, diagnoses or medical/legal advice.
3. Never confirm an appointment yourself. Your job is only to collect: (a) the service, (b) the date, (c) the time, (d) the customer's name. Once all four are known, repeat them back in one short message and ask the customer to confirm. Set booking.ready_to_book = true ONLY after the customer has confirmed. The booking system then checks the calendar and sends the confirmation.
4. Appointments are possible only during the booking hours listed below. If the customer asks for a time outside them, politely offer the booking hours instead.
5. Hand off to a human (needs_human = true, with a short polite reply) when the customer asks for a person, is upset or complaining, asks for medical/legal advice, asks about something not in the knowledge base, or when you are unsure.
6. Reply in the customer's language. Keep replies short: at most 3 short sentences or a short list. Plain text only — no markdown, no headings, no bold.
7. Capture lead details (name, phone, email, service interest) whenever the customer shares them.
8. If the customer message is a placeholder such as "[The customer sent a image message ...]", politely ask them to type their question.
9. confidence = how fully your reply is supported by the knowledge base (1.0 = fully supported, below 0.6 = unsure).
10. Every knowledge base row has an id in square brackets, e.g. [S1]. In kb_refs list the ids of EVERY row you used for the reply (empty list for greetings or booking steps).${strictMode ? ' For FAQ answers the system will send the referenced rows word for word, so choose the ids carefully and keep the reply short.' : ''}${requireConsent ? `
11. Before collecting booking or contact details, ask once: "May we save your name and contact details in our records to arrange your appointment? Please reply yes or no." Record the answer in lead.consent. If the customer says no, keep helping but do not store or ask again.` : ''}

BOOKING HOURS: ${config.opening_time}–${config.closing_time} (${zone}), closed on: ${config.closed_days || 'none'}. Appointment length: ${config.slot_minutes} minutes.

APPROVED KNOWLEDGE BASE
${kb_text}`;

const profile = lead
  ? `name: ${lead.name || 'unknown'}; service interest: ${lead.service_interest || 'unknown'}; previous booking: ${lead.booking_datetime || 'none'}`
  : 'new customer, no previous chats';

const liveContext = `TODAY: ${now.toFormat('cccc, d LLLL yyyy')} · current time ${now.toFormat('HH:mm')} (${zone}). Resolve relative dates such as "tomorrow" or "next Monday" into absolute dates.
CHANNEL: ${message.channel}. CUSTOMER PROFILE: ${profile}.`;

// JSON schema the model MUST follow (structured outputs) ---------------------
const nullableString = { anyOf: [{ type: 'string' }, { type: 'null' }] };
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['intent', 'reply', 'confidence', 'needs_human', 'handoff_reason', 'kb_refs', 'lead', 'booking'],
  properties: {
    intent: {
      type: 'string',
      enum: ['faq', 'booking', 'lead', 'handoff', 'smalltalk'],
      description: 'faq = question answerable from the knowledge base · booking = wants an appointment · lead = sharing contact details / interest · handoff = needs a human · smalltalk = greeting or thanks',
    },
    reply: { type: 'string', description: "The exact message to send to the customer. Plain text, short, friendly, in the customer's language." },
    confidence: { type: 'number', description: '0 to 1. How fully the reply is supported by the approved knowledge base.' },
    needs_human: { type: 'boolean', description: 'true when a human must take over this conversation.' },
    handoff_reason: { ...nullableString, description: 'Short reason when needs_human is true, otherwise null.' },
    kb_refs: { type: 'array', items: { type: 'string' }, description: 'Ids of the knowledge base rows used for this reply, e.g. ["S1", "H2"]. Empty if none were needed.' },
    lead: {
      type: 'object',
      additionalProperties: false,
      required: ['name', 'phone', 'email', 'service_interest', 'consent'],
      properties: {
        name: nullableString,
        phone: nullableString,
        email: nullableString,
        service_interest: nullableString,
        consent: { type: 'string', enum: ['yes', 'no', 'unknown'], description: 'Whether the customer agreed to have their details stored. "unknown" until they answer.' },
      },
    },
    booking: {
      type: 'object',
      additionalProperties: false,
      required: ['requested', 'service', 'date', 'time', 'ready_to_book'],
      properties: {
        requested: { type: 'boolean', description: 'true if the customer wants an appointment.' },
        service: nullableString,
        date: { ...nullableString, description: 'Absolute date as YYYY-MM-DD, resolved from TODAY.' },
        time: { ...nullableString, description: 'Start time as HH:MM in 24-hour format.' },
        ready_to_book: { type: 'boolean', description: 'true ONLY when service, date, time and name are all known AND the customer confirmed them in their latest message.' },
      },
    },
  },
};

const claude_request = {
  model: config.claude_model || 'claude-opus-5-5',
  max_tokens: 2048,
  system: [
    { type: 'text', text: stableRules, cache_control: { type: 'ephemeral' } },   // stable → cached between messages
    { type: 'text', text: liveContext },                                          // changes every call → after the cache breakpoint
  ],
  messages: [...history, { role: 'user', content: message.text }],
  output_config: {
    effort: config.claude_effort || 'low',
    format: { type: 'json_schema', schema },
  },
};

return [{ json: { ...ctx, claude_request } }];

// ============================================================================
// 4 · PARSE CLAUDE RESPONSE + GUARDRAILS
// ----------------------------------------------------------------------------
// Reads the model's JSON and then applies DETERMINISTIC checks that the model
// cannot talk its way around. Any failed check → "handoff" (safe default).
//   • unreadable / refused / errored API response
//   • empty reply
//   • the model itself asked for a human
//   • confidence below the threshold set in Client Config
//   • PRICE GUARD: every money amount in the reply must exist in the knowledge base
//   • the customer explicitly asked for a person
// Also: validates kb_refs, applies strict mode (verbatim sheet rows for FAQs)
// and the optional consent rule.
// Output adds: ai, guard[], needs_human, decision ("answer" | "book" | "handoff"),
//              lead_merged, consent_given, save_personal_details, tokens_used
// ============================================================================

const ctx = $('Build Claude Request').first().json;
const res = $input.first().json || {};
const config = ctx.config;

// --- 1. Read the structured JSON -------------------------------------------
let ai = null;
let problem = null;
if (res.error) problem = 'ai_api_error';
else if (res.stop_reason === 'refusal') problem = 'ai_refusal';
else if (res.stop_reason === 'max_tokens') problem = 'ai_output_truncated';
else {
  try {
    const text = (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('').trim();
    ai = JSON.parse(text);
  } catch (e) {
    problem = 'ai_output_unreadable';
  }
}
if (!ai || typeof ai !== 'object') { ai = {}; problem = problem || 'ai_output_unreadable'; }

// --- 2. Normalize fields with safe defaults ----------------------------------
const INTENTS = ['faq', 'booking', 'lead', 'handoff', 'smalltalk'];
ai.intent = INTENTS.includes(ai.intent) ? ai.intent : 'faq';
ai.reply = String(ai.reply || '').trim();
ai.confidence = Math.max(0, Math.min(1, Number(ai.confidence) || 0));
ai.needs_human = Boolean(ai.needs_human);
ai.handoff_reason = ai.handoff_reason ? String(ai.handoff_reason) : null;
ai.lead = Object.assign({ name: null, phone: null, email: null, service_interest: null, consent: 'unknown' }, ai.lead || {});
ai.lead.consent = ['yes', 'no'].includes(ai.lead.consent) ? ai.lead.consent : 'unknown';
ai.booking = Object.assign({ requested: false, service: null, date: null, time: null, ready_to_book: false }, ai.booking || {});

// Knowledge-base references: keep only ids that really exist in the sheet.
const kbById = {};
for (const row of ctx.kb_rows || []) kbById[row.id] = row;
ai.kb_refs = (Array.isArray(ai.kb_refs) ? ai.kb_refs : []).map((id) => String(id).replace(/[\[\]\s]/g, '').toUpperCase()).filter((id) => kbById[id]);

// Strict mode: FAQ answers are the sheet rows word for word, never the model's wording.
const strictMode = String(config.reply_mode || 'assistant').toLowerCase() === 'strict';
if (strictMode && ai.intent === 'faq' && !problem) {
  if (ai.kb_refs.length) ai.reply = ai.kb_refs.map((id) => `${kbById[id].title}: ${kbById[id].content}`).join('\n');
  else { ai.needs_human = true; ai.handoff_reason = ai.handoff_reason || 'strict mode: answer not backed by a knowledge base row'; }
}

// --- 3. Guardrails (outside the model) ---------------------------------------
const guard = [];
if (problem) guard.push(problem);
if (!ai.reply) guard.push('empty_reply');
if (ai.needs_human) guard.push(ai.handoff_reason ? `model: ${ai.handoff_reason}` : 'model_requested_handoff');

const threshold = Number(config.handoff_confidence_threshold) || 0.6;
if (!problem && ai.confidence < threshold) guard.push(`low_confidence (${ai.confidence} < ${threshold})`);

// Price guard: any currency amount in the reply must appear in the approved knowledge base.
const MONEY = /(?:PKR|Rs\.?|₨|\$|USD|€|EUR|£|GBP|AED|SAR|INR|₹)\s?\d[\d,]*(?:\.\d+)?|\d[\d,]*(?:\.\d+)?\s?(?:PKR|Rs\.?|USD|EUR|GBP|AED|SAR|INR|dollars|rupees|euros|pounds)\b/gi;
const kbNumbers = new Set((String(ctx.kb_text).match(/\d[\d,]*(?:\.\d+)?/g) || []).map((n) => n.replace(/,/g, '')));
for (const amount of ai.reply.match(MONEY) || []) {
  const n = (amount.match(/\d[\d,]*(?:\.\d+)?/) || [''])[0].replace(/,/g, '');
  if (n && !kbNumbers.has(n)) { guard.push(`price_not_in_knowledge_base: ${amount.trim()}`); break; }
}

// Explicit request for a person (checked on the customer's own words).
if (/\b(human|real person|speak to (?:someone|a person|the doctor|the owner)|talk to (?:someone|a person|the doctor|the owner)|manager|complaint|complain)\b/i.test(ctx.message.text)) {
  guard.push('customer_asked_for_human');
}

const needs_human = guard.length > 0;
const b = ai.booking;
const booking_ready = !needs_human && b.ready_to_book && b.service && b.date && b.time;
const decision = needs_human ? 'handoff' : booking_ready ? 'book' : 'answer';

// --- 4. Merge lead details: this turn > existing sheet row > channel profile --
const old = ctx.lead || {};
const lead_merged = {
  name: ai.lead.name || old.name || ctx.message.contact_name || '',
  phone: ai.lead.phone || old.phone || (ctx.message.channel === 'whatsapp' ? ctx.message.contact_id : ''),
  email: ai.lead.email || old.email || '',
  service_interest: ai.lead.service_interest || b.service || old.service_interest || '',
};

// --- 5. Consent (only when require_consent is true in Client Config) --------
// Personal details (name, phone, email) are written to the Leads sheet only
// with consent. The row itself always exists: it carries the bot/human status.
const requireConsent = String(config.require_consent) === 'true';
const consent_given = ai.lead.consent === 'yes' || Boolean(old.consent_at);
const save_personal_details = !requireConsent || consent_given;

const usage = res.usage || {};
const tokens_used = (Number(usage.input_tokens) || 0) + (Number(usage.cache_read_input_tokens) || 0) + (Number(usage.cache_creation_input_tokens) || 0) + (Number(usage.output_tokens) || 0);

return [{ json: { ...ctx, ai, guard, needs_human, decision, lead_merged, consent_given, save_personal_details, tokens_used } }];

// ============================================================================
// 5 · VALIDATE BOOKING SLOT
// ----------------------------------------------------------------------------
// The model only proposes a date + time. The WORKFLOW decides whether that slot
// is allowed: in the future, on an open day, inside booking hours. Only a valid
// slot is checked against Google Calendar.
// Output adds: slot { valid, error, error_text, start_iso, end_iso, human }
// ============================================================================

const ctx = $input.first().json;
const config = ctx.config;
const b = ctx.ai.booking;
const zone = config.timezone || 'UTC';
const slotMinutes = Number(config.slot_minutes) || 30;

const start = DateTime.fromISO(`${b.date}T${b.time}`, { zone });
let error = null;

if (!start.isValid) error = 'invalid_datetime';
else {
  const now = DateTime.now().setZone(zone);
  const [oh, om] = String(config.opening_time || '09:00').split(':').map(Number);
  const [ch, cm] = String(config.closing_time || '18:00').split(':').map(Number);
  const closedDays = String(config.closed_days || '').split(',').map((d) => d.trim().toLowerCase()).filter(Boolean);
  const opens = start.set({ hour: oh, minute: om, second: 0, millisecond: 0 });
  const closes = start.set({ hour: ch, minute: cm, second: 0, millisecond: 0 });

  if (start <= now) error = 'in_the_past';
  else if (closedDays.includes(start.weekdayLong.toLowerCase())) error = 'closed_day';
  else if (start < opens || start.plus({ minutes: slotMinutes }) > closes) error = 'outside_hours';
}

const end = start.isValid ? start.plus({ minutes: slotMinutes }) : null;

const ERROR_TEXT = {
  in_the_past: 'That time has already passed.',
  closed_day: "We're closed on that day.",
  outside_hours: 'That time is outside our booking hours.',
  invalid_datetime: "I couldn't understand that date or time.",
};

return [{
  json: {
    ...ctx,
    slot: {
      valid: !error,
      error,
      error_text: error ? ERROR_TEXT[error] : '',
      start_iso: start.isValid ? start.toISO() : null,
      end_iso: end ? end.toISO() : null,
      human: start.isValid ? start.toFormat("cccc d LLLL yyyy 'at' h:mm a") : `${b.date} ${b.time}`,
    },
  },
}];

